/**
 * Canvas 2D paper-doll renderer for dialogue portrait and battle dressup.
 *
 * The renderer consumes launcher/web/assets/dressup/manifest.json, which is
 * generated by tools/bake-dressup-offline.py from data/items plus XFL rig
 * metadata. Baked frames carry registration-point offsets exported from FFDec
 * SVG metadata, so Canvas drawing preserves Flash attachMovie origin behavior.
 */
var DressupDollRenderer = (function() {
    'use strict';

    var FIELD_COLORS = {
        '身体': '#648fff',
        '上臂': '#785ef0',
        '左下臂': '#dc267f',
        '右下臂': '#dc267f',
        '左手': '#fe6100',
        '右手': '#fe6100',
        '屁股': '#ffb000',
        '左大腿': '#4db05a',
        '右大腿': '#4db05a',
        '小腿': '#2a9d8f',
        '脚': '#9c755f',
        '脸型': '#e8c1a0',
        '发型': '#8f6b32',
        '面具': '#b56576',
        '刀_装扮': '#d62828',
        '刀1_装扮': '#d62828',
        '刀2_装扮': '#b21e35',
        '刀3_装扮': '#8c1d40',
        '长枪_装扮': '#277da1',
        '手枪_装扮': '#577590',
        '手枪2_装扮': '#577590',
        '手雷_装扮': '#6d597a'
    };

    var PLACEHOLDER_W = 64;
    var PLACEHOLDER_H = 42;
    var DIRECT_SKIN_FIELD = '__direct_skin__';
    if (typeof AssetTimeline === 'undefined' || !AssetTimeline) {
        throw new Error('AssetTimeline must be loaded before dressup-doll-renderer.js');
    }
    var Timeline = AssetTimeline;

    function loadManifest(url) {
        return fetch(url).then(function(response) {
            if (!response.ok) throw new Error('Failed to load dressup manifest: ' + response.status);
            return response.json();
        }).then(function(data) {
            data.__baseUrl = new URL(url, document.baseURI).href;
            return data;
        });
    }

    function collectItemsByUse(manifest) {
        var byUse = {};
        var items = manifest && manifest.items ? manifest.items : {};
        Object.keys(items).sort().forEach(function(name) {
            var item = items[name];
            var use = item.use || '<unknown>';
            if (!byUse[use]) byUse[use] = [];
            byUse[use].push(name);
        });
        return byUse;
    }

    function mergeFields(target, fields) {
        if (!fields) return;
        Object.keys(fields).forEach(function(field) {
            target[field] = fields[field];
        });
    }

    // 武器槽位 → 该槽允许贡献的装扮字段（对齐 AS2 DressupInitializer 的逐槽赋值、
    // 空槽不挂载语义）。烘焙层对手枪类物品固定写 手枪_装扮+手枪2_装扮 双字段
    // （tools/bake-dressup-offline.py，槽位无关数据）；合并时若不按槽过滤，一把
    // 手枪会同时污染两个手枪 holder（幻影双枪 / 腿套双枪）。刀 同槽多字段
    // （刀身/刀鞘/复合部件）属 AS2 dressup/dressup2/dressup3 的合法语义，保留。
    var WEAPON_SLOT_FIELDS = {
        '长枪': ['长枪_装扮'],
        '手枪': ['手枪_装扮'],
        '手枪2': ['手枪2_装扮'],
        '刀': ['刀_装扮', '刀1_装扮', '刀2_装扮', '刀3_装扮'],
        '手雷': ['手雷_装扮']
    };
    var ALL_WEAPON_FIELDS = {};
    Object.keys(WEAPON_SLOT_FIELDS).forEach(function(slotKey) {
        WEAPON_SLOT_FIELDS[slotKey].forEach(function(field) { ALL_WEAPON_FIELDS[field] = true; });
    });

    // 武器条目只收当前槽（非标准槽键时按物品 use）允许的武器字段；非武器条目原样合并。
    function mergeEquipmentFields(target, slot, item, gender) {
        var fields = item && item.fieldsByGender ? item.fieldsByGender[gender] : null;
        if (!fields) return;
        var allowed = WEAPON_SLOT_FIELDS[slot] || WEAPON_SLOT_FIELDS[item.use] || null;
        if (!allowed) {
            mergeFields(target, fields);
            return;
        }
        Object.keys(fields).forEach(function(field) {
            if (ALL_WEAPON_FIELDS[field] === true && allowed.indexOf(field) < 0) return;
            target[field] = fields[field];
        });
    }

    function buildStateFromEquipment(manifest, options) {
        options = options || {};
        var gender = options.gender || '男';
        var keyMap = {};
        var equipment = options.equipment || {};
        Object.keys(equipment).forEach(function(slot) {
            var itemName = equipment[slot];
            var item = manifest.items[itemName];
            if (item && item.fieldsByGender) {
                mergeEquipmentFields(keyMap, slot, item, gender);
            }
        });
        mergeFields(keyMap, options.appearance);
        mergeFields(keyMap, options.keyMap);
        var state = {
            gender: gender,
            keyMap: keyMap
        };
        if (options.fitFields && options.fitFields.length) {
            state.fitFields = options.fitFields.slice ? options.fitFields.slice(0) : options.fitFields;
        }
        if (options.drawFields && options.drawFields.length) {
            state.drawFields = options.drawFields.slice ? options.drawFields.slice(0) : options.drawFields;
        }
        if (typeof options.zoom === 'number') state.zoom = options.zoom;
        if (typeof options.margin === 'number') state.margin = options.margin;
        var fitEnvelope = normalizeBounds(options.fitEnvelope);
        if (fitEnvelope) state.fitEnvelope = fitEnvelope;
        if (options.rig) state.rig = options.rig;
        if (options.stateLabel) state.stateLabel = options.stateLabel;
        if (options.attackMode) state.attackMode = options.attackMode;
        if (options.strictFields === true) state.strictFields = true;
        if (options['攻击模式']) state['攻击模式'] = options['攻击模式'];
        if (options.directSkinKey) {
            state.directSkinKey = String(options.directSkinKey);
            state.keyMap[DIRECT_SKIN_FIELD] = state.directSkinKey;
            state.fitFields = [DIRECT_SKIN_FIELD];
            state.drawFields = [DIRECT_SKIN_FIELD];
        }
        return state;
    }

    function matrixOf(holder) {
        var m = holder.matrix || {};
        return matrixFrom(m);
    }

    function matrixFrom(value) {
        var m = value || {};
        return {
            a: numberOr(m.a, 1),
            b: numberOr(m.b, 0),
            c: numberOr(m.c, 0),
            d: numberOr(m.d, 1),
            tx: numberOr(m.tx, 0),
            ty: numberOr(m.ty, 0)
        };
    }

    function multiplyMatrix(left, right) {
        return {
            a: left.a * right.a + left.c * right.b,
            b: left.b * right.a + left.d * right.b,
            c: left.a * right.c + left.c * right.d,
            d: left.b * right.c + left.d * right.d,
            tx: left.a * right.tx + left.c * right.ty + left.tx,
            ty: left.b * right.tx + left.d * right.ty + left.ty
        };
    }

    function numberOr(value, fallback) {
        return typeof value === 'number' && isFinite(value) ? value : fallback;
    }

    function copyBounds(bounds) {
        return {
            minX: bounds.minX,
            minY: bounds.minY,
            maxX: bounds.maxX,
            maxY: bounds.maxY
        };
    }

    function normalizeBounds(value) {
        if (!value || typeof value !== 'object') return null;
        var minX = Number(value.minX);
        var minY = Number(value.minY);
        var maxX = Number(value.maxX);
        var maxY = Number(value.maxY);
        if (!isFinite(minX) || !isFinite(minY) || !isFinite(maxX) || !isFinite(maxY)
                || !(maxX > minX) || !(maxY > minY)) {
            return null;
        }
        return { minX:minX, minY:minY, maxX:maxX, maxY:maxY };
    }

    function expandBounds(bounds, x, y) {
        bounds.minX = Math.min(bounds.minX, x);
        bounds.minY = Math.min(bounds.minY, y);
        bounds.maxX = Math.max(bounds.maxX, x);
        bounds.maxY = Math.max(bounds.maxY, y);
    }

    function skinZoom(skin) {
        if (!skin || !skin.export) return 1;
        var zoom = numberOr(skin.export.zoom, 1);
        return zoom > 0 ? zoom : 1;
    }

    function frameDrawSize(skin, frame) {
        if (!skin || !skin.export) return { width: PLACEHOLDER_W, height: PLACEHOLDER_H };
        var zoom = skinZoom(skin);
        frame = frame || {};
        return {
            width: Math.max(1, numberOr(frame.width, numberOr(skin.export.width, PLACEHOLDER_W * zoom)) / zoom),
            height: Math.max(1, numberOr(frame.height, numberOr(skin.export.height, PLACEHOLDER_H * zoom)) / zoom)
        };
    }

    function frameOrigin(skin, frame) {
        if (!skin || !skin.export || !frame) return { x: 0, y: 0 };
        var zoom = skinZoom(skin);
        return {
            x: numberOr(frame.originX, 0) / zoom,
            y: numberOr(frame.originY, 0) / zoom
        };
    }

    function playbackFrames(entry) {
        return Timeline.playbackFrames(entry);
    }

    function skinBoundsSize(skin) {
        if (!skin || !skin.export) return { width: PLACEHOLDER_W, height: PLACEHOLDER_H };
        var frames = playbackFrames(skin);
        if (!frames.length) return frameDrawSize(skin, null);
        var maxWidth = 1;
        var maxHeight = 1;
        frames.forEach(function(frame) {
            var size = frameDrawSize(skin, frame);
            maxWidth = Math.max(maxWidth, size.width);
            maxHeight = Math.max(maxHeight, size.height);
        });
        return { width: maxWidth, height: maxHeight };
    }

    function nestedLayers(entry, drawOrder) {
        var nested = entry && entry.export && entry.export.nestedAnimation;
        var layers = nested && nested.layers ? nested.layers : [];
        if (!drawOrder) return layers;
        return layers.filter(function(layer) {
            return (layer.drawOrder || 'over') === drawOrder;
        });
    }

    function attackModeForState(stateContext) {
        var explicit = stateContext && (stateContext.attackMode || stateContext['攻击模式']);
        if (explicit) return explicit;
        var label = stateContext && stateContext.stateLabel || '';
        if (label === '手枪站立') return '手枪';
        if (label === '手枪2站立') return '手枪2';
        if (label === '双枪站立') return '双枪';
        if (label === '长枪站立') return '长枪';
        if (label === '兵器站立') return '兵器';
        return '';
    }

    function entryWithRuntimeVariant(entry, stateContext) {
        if (!entry || !entry.export || !entry.runtimeVariants || !entry.conditionalVisibility) return entry;
        var conditional = entry.conditionalVisibility;
        if (conditional.property !== '攻击模式') return entry;
        var visibleWhen = conditional.visibleWhen || [];
        var attackMode = attackModeForState(stateContext);
        if (visibleWhen.indexOf(attackMode) >= 0) return entry;
        var variant = entry.runtimeVariants[conditional.hiddenVariant || 'neutral'];
        return variant && variant.export ? variant : entry;
    }

    function renderableForHolder(holder, manifest, keyMap, stateContext) {
        var skinKey = keyMap ? keyMap[holder.field] : null;
        var skin = skinKey && manifest.skinKeys ? manifest.skinKeys[skinKey] : null;
        if (skin && skin.export) {
            return {
                kind: 'skin',
                key: skinKey,
                entry: entryWithRuntimeVariant(skin, stateContext),
                innerMatrix: null,
                covered: skin.covered
            };
        }
        if ((!skin || skin.covered === false) && holder.fallbackBasic && holder.basic && holder.basic.export) {
            return {
                kind: 'basic',
                key: holder.basic.linkageId || holder.basic.libraryItemName || holder.field,
                entry: holder.basic,
                innerMatrix: matrixFrom(holder.basic.matrix),
                covered: true
            };
        }
        return {
            kind: 'missing',
            key: skinKey,
            entry: null,
            innerMatrix: null,
            covered: skin ? skin.covered : false
        };
    }

    function matrixForRenderable(holder, renderable) {
        var matrix = matrixOf(holder);
        if (renderable && renderable.innerMatrix) {
            matrix = multiplyMatrix(matrix, renderable.innerMatrix);
        }
        return matrix;
    }

    function expandEntryBounds(bounds, entry, matrix) {
        if (!entry) return;
        var m = matrix;
        var frames = playbackFrames(entry);
        frames = frames.length ? frames : [null];
        frames.forEach(function(frame) {
            var drawSize = frameDrawSize(entry, frame);
            var origin = frameOrigin(entry, frame);
            var left = -origin.x;
            var top = -origin.y;
            var right = left + drawSize.width;
            var bottom = top + drawSize.height;
            var corners = [
                [left, top],
                [right, top],
                [left, bottom],
                [right, bottom]
            ];
            corners.forEach(function(point) {
                var x = m.a * point[0] + m.c * point[1] + m.tx;
                var y = m.b * point[0] + m.d * point[1] + m.ty;
                expandBounds(bounds, x, y);
            });
        });
    }

    function expandNestedLayerBounds(bounds, layer, parentMatrix) {
        if (!layer || !layer.export) return;
        var matrix = multiplyMatrix(parentMatrix, matrixFrom(layer.matrix));
        nestedLayers(layer).forEach(function(childLayer) {
            expandNestedLayerBounds(bounds, childLayer, matrix);
        });
        expandEntryBounds(bounds, layer, matrix);
    }

    function computeBounds(holders, manifest, keyMap, debugPlaceholders, stateContext) {
        var bounds = { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity };
        holders.forEach(function(holder) {
            var renderable = renderableForHolder(holder, manifest, keyMap, stateContext);
            if (!renderable.entry && !debugPlaceholders) return;
            var m = matrixForRenderable(holder, renderable);
            if (renderable.entry) {
                nestedLayers(renderable.entry).forEach(function(layer) {
                    expandNestedLayerBounds(bounds, layer, m);
                });
                expandEntryBounds(bounds, renderable.entry, m);
                return;
            }
            var frames = renderable.entry && renderable.entry.frames && renderable.entry.frames.length
                ? renderable.entry.frames
                : [null];
            frames.forEach(function(frame) {
                var drawSize = renderable.entry ? frameDrawSize(renderable.entry, frame) : { width: PLACEHOLDER_W, height: PLACEHOLDER_H };
                var origin = renderable.entry ? frameOrigin(renderable.entry, frame) : { x: 0, y: 0 };
                var left = -origin.x;
                var top = -origin.y;
                var right = left + drawSize.width;
                var bottom = top + drawSize.height;
                var corners = [
                    [left, top],
                    [right, top],
                    [left, bottom],
                    [right, bottom]
                ];
                corners.forEach(function(point) {
                    var x = m.a * point[0] + m.c * point[1] + m.tx;
                    var y = m.b * point[0] + m.d * point[1] + m.ty;
                    expandBounds(bounds, x, y);
                });
            });
        });
        if (!isFinite(bounds.minX)) {
            bounds = { minX: -80, minY: -120, maxX: 180, maxY: 280 };
        }
        return bounds;
    }

    function holdersForFit(holders, fitFields, strictFields) {
        if (!fitFields || !fitFields.length) return holders;
        var selected = {};
        fitFields.forEach(function(field) {
            if (field) selected[field] = true;
        });
        var result = holders.filter(function(holder) {
            return holder && selected[holder.field];
        });
        return result.length || strictFields ? result : holders;
    }

    function holdersForDraw(holders, drawFields, strictFields) {
        if (!drawFields || !drawFields.length) return holders;
        var selected = {};
        drawFields.forEach(function(field) {
            if (field) selected[field] = true;
        });
        var result = holders.filter(function(holder) {
            return holder && selected[holder.field];
        });
        return result.length || strictFields ? result : holders;
    }

    function resolveRigState(manifest, gender, state, options) {
        manifest = manifest || {};
        state = state || {};
        options = options || {};
        if (state.directSkinKey && manifest.skinKeys && manifest.skinKeys[state.directSkinKey]) {
            return {
                rig: 'product-direct',
                stateLabel: 'product-direct',
                holders: [{
                    field: DIRECT_SKIN_FIELD,
                    matrix: {a:1, b:0, c:0, d:1, tx:0, ty:0},
                    fallbackBasic: false,
                    basic: null
                }]
            };
        }
        var rigName = state.rig || options.rig || 'dialogue';
        if (rigName !== 'dialogue') {
            var namedRig = manifest.rigs && manifest.rigs[rigName];
            var namedGender = namedRig && namedRig.genders && (namedRig.genders[gender] || namedRig.genders['男']);
            var stateLabel = state.stateLabel || options.stateLabel || (namedRig && namedRig.defaultState) || '';
            var namedState = namedGender && namedGender.states && namedGender.states[stateLabel];
            if (namedState) {
                return {
                    rig: rigName,
                    stateLabel: stateLabel,
                    holders: namedState.holders || []
                };
            }
        }
        var rigGender = manifest.rig && manifest.rig.genders ? manifest.rig.genders[gender] : null;
        return {
            rig: 'dialogue',
            stateLabel: '',
            holders: rigGender ? rigGender.holders || [] : []
        };
    }

    /**
     * Resolves fit geometry without touching Canvas, loading images or advancing animation.
     * Consumers can union several returned bounds into one session-owned fit envelope, then
     * pass that envelope back through state.fitEnvelope. This stays opt-in: callers that omit
     * fitEnvelope retain the historical per-render auto-fit behavior.
     */
    function resolveMeasurement(manifest, state, options) {
        manifest = manifest || {};
        state = state || { gender:'男', keyMap:{} };
        options = options || {};
        var gender = state.gender || '男';
        var rigState = resolveRigState(manifest, gender, state, options);
        var stateContext = {};
        Object.keys(state).forEach(function(key) {
            stateContext[key] = state[key];
        });
        stateContext.rig = rigState.rig;
        stateContext.stateLabel = rigState.stateLabel;
        var holders = rigState.holders || [];
        var strictFields = state.strictFields === true || options.strictFields === true;
        var fitHolders = holdersForFit(
            holders,
            state.fitFields || options.fitFields,
            strictFields
        );
        var bounds = computeBounds(
            fitHolders,
            manifest,
            state.keyMap || {},
            options.debugPlaceholders === true,
            stateContext
        );
        return {
            gender:gender,
            rigState:rigState,
            stateContext:stateContext,
            holders:holders,
            fitHolders:fitHolders,
            strictFields:strictFields,
            bounds:bounds
        };
    }

    function measureState(manifest, state, options) {
        var measured = resolveMeasurement(manifest, state, options);
        return {
            gender:measured.gender,
            rig:measured.rigState.rig,
            stateLabel:measured.rigState.stateLabel,
            fitHolders:measured.fitHolders.length,
            totalHolders:measured.holders.length,
            strictFields:measured.strictFields,
            bounds:copyBounds(measured.bounds)
        };
    }

    function measureEnvelope(manifest, state, variants, options, padding) {
        state = state || { gender:'男', keyMap:{} };
        variants = variants && variants.length ? variants : [{}];
        var union = null;
        for (var i = 0; i < variants.length; i++) {
            var variantState = {};
            Object.keys(state).forEach(function(key) { variantState[key] = state[key]; });
            Object.keys(variants[i] || {}).forEach(function(key) {
                variantState[key] = variants[i][key];
            });
            var bounds = resolveMeasurement(manifest, variantState, options).bounds;
            if (!union) {
                union = copyBounds(bounds);
            } else {
                union.minX = Math.min(union.minX, bounds.minX);
                union.minY = Math.min(union.minY, bounds.minY);
                union.maxX = Math.max(union.maxX, bounds.maxX);
                union.maxY = Math.max(union.maxY, bounds.maxY);
            }
        }
        var ratio = Number(padding);
        if (!(ratio >= 0) || !isFinite(ratio)) ratio = 0;
        var width = Math.max(1, union.maxX - union.minX);
        var height = Math.max(1, union.maxY - union.minY);
        return {
            minX:union.minX - width * ratio,
            minY:union.minY - height * ratio,
            maxX:union.maxX + width * ratio,
            maxY:union.maxY + height * ratio
        };
    }

    function withFitEnvelope(renderer, state, variants, padding) {
        if (renderer && typeof renderer.measureEnvelope === 'function') {
            state.fitEnvelope = renderer.measureEnvelope(state, variants, padding);
        }
        return state;
    }

    function resolveImageUri(uri, manifest) {
        if (!uri) return null;
        if (/^(https?:|data:|blob:|\/)/.test(uri)) return uri;
        return new URL(uri, manifest.__baseUrl || document.baseURI).href;
    }

    function selectSkinFrame(skin, nowMs, fallbackFps) {
        if (!skin) return { frame: null, animated: false };
        var frames = playbackFrames(skin);
        if (!frames.length) {
            return {
                frame: skin.export ? { uri: skin.export.uri, width: skin.export.width, height: skin.export.height } : null,
                animated: false
            };
        }
        return Timeline.select(skin, nowMs, {
            frames: frames,
            fallbackFps: fallbackFps,
            defaultFps: fallbackFps,
            identity: ['uri', 'width', 'height', 'originX', 'originY']
        });
    }

    function createImageCache() {
        return {};
    }

    function loadImage(cache, uri, onload) {
        if (!uri) return null;
        if (cache[uri]) return cache[uri];
        var image = new Image();
        cache[uri] = image;
        image.onload = onload;
        image.onerror = onload;
        image.src = uri;
        return image;
    }

    function drawPlaceholder(ctx, holder, skinKey, covered) {
        var color = FIELD_COLORS[holder.field] || '#6c757d';
        ctx.save();
        ctx.globalAlpha = covered === false ? 0.38 : 0.78;
        ctx.fillStyle = color;
        ctx.strokeStyle = 'rgba(255,255,255,0.78)';
        ctx.lineWidth = 1;
        roundedRect(ctx, 0, 0, PLACEHOLDER_W, PLACEHOLDER_H, 4);
        ctx.fill();
        ctx.stroke();
        ctx.globalAlpha = 1;
        ctx.fillStyle = '#ffffff';
        ctx.font = '8px "Microsoft YaHei", Arial, sans-serif';
        ctx.textBaseline = 'top';
        ctx.fillText(holder.field, 4, 4);
        ctx.fillStyle = 'rgba(255,255,255,0.82)';
        ctx.font = '6px "Microsoft YaHei", Arial, sans-serif';
        wrapText(ctx, skinKey || '(empty)', 4, 17, PLACEHOLDER_W - 8, 8, 2);
        ctx.restore();
    }

    function roundedRect(ctx, x, y, w, h, r) {
        ctx.beginPath();
        ctx.moveTo(x + r, y);
        ctx.lineTo(x + w - r, y);
        ctx.quadraticCurveTo(x + w, y, x + w, y + r);
        ctx.lineTo(x + w, y + h - r);
        ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
        ctx.lineTo(x + r, y + h);
        ctx.quadraticCurveTo(x, y + h, x, y + h - r);
        ctx.lineTo(x, y + r);
        ctx.quadraticCurveTo(x, y, x + r, y);
        ctx.closePath();
    }

    function wrapText(ctx, text, x, y, maxWidth, lineHeight, maxLines) {
        var line = '';
        var lines = 0;
        for (var i = 0; i < text.length; i++) {
            var next = line + text.charAt(i);
            if (ctx.measureText(next).width > maxWidth && line) {
                ctx.fillText(line, x, y + lines * lineHeight);
                line = text.charAt(i);
                lines++;
                if (lines >= maxLines) return;
            } else {
                line = next;
            }
        }
        if (line && lines < maxLines) ctx.fillText(line, x, y + lines * lineHeight);
    }

    function applyMatrix(ctx, matrix) {
        var m = matrix.a === undefined ? matrixOf(matrix) : matrix;
        ctx.transform(m.a, m.b, m.c, m.d, m.tx, m.ty);
    }

    function drawFrameImage(ctx, entry, frame, image) {
        var drawSize = frameDrawSize(entry, frame);
        var origin = frameOrigin(entry, frame);
        ctx.drawImage(image, -origin.x, -origin.y, drawSize.width, drawSize.height);
    }

    function create(canvas, options) {
        options = options || {};
        var ctx = canvas.getContext('2d');
        var manifest = options.manifest;
        var imageCache = createImageCache();
        var lastState = null;
        var animationRequest = null;
        var destroyed = false;
        var animationEnabled = options.animate !== false;
        var fallbackFps = numberOr(options.fps, 24);
        var animationFrameInterval = 1000 / Math.max(1, fallbackFps);
        var lastAnimationRenderAt = null;
        var configuredPixelRatio = Number(options.pixelRatio);
        var debugPlaceholders = options.debugPlaceholders === true;

        function scheduleAnimation() {
            if (destroyed || !animationEnabled) return;
            if (animationRequest !== null) return;
            animationRequest = window.requestAnimationFrame(function(timestamp) {
                animationRequest = null;
                if (destroyed || !animationEnabled || !lastState) return;
                var nowMs = Number(timestamp);
                if (!isFinite(nowMs)) {
                    nowMs = window.performance && window.performance.now
                        ? window.performance.now() : Date.now();
                }
                var elapsed = lastAnimationRenderAt === null
                    ? animationFrameInterval : nowMs - lastAnimationRenderAt;
                if (elapsed + 0.5 >= animationFrameInterval) {
                    lastAnimationRenderAt = lastAnimationRenderAt === null
                        ? nowMs : nowMs - (elapsed % animationFrameInterval);
                    render(lastState);
                } else {
                    scheduleAnimation();
                }
            });
        }

        function setupCanvas() {
            var dpr = configuredPixelRatio > 0 ? configuredPixelRatio : (window.devicePixelRatio || 1);
            var rect = canvas.getBoundingClientRect();
            // 普通纸娃娃继续按物理 rect（包含 PanelScale）建 backing，保留既有高 DPI 清晰度。
            // 交互检视器显式忽略自身 CSS zoom，避免 backing 随每次缩放反复改尺寸。
            var layoutWidth = options.ignoreCssTransforms === true ? canvas.clientWidth : rect.width;
            var layoutHeight = options.ignoreCssTransforms === true ? canvas.clientHeight : rect.height;
            var cssW = Math.max(1, Math.round(layoutWidth || canvas.clientWidth || rect.width || options.width || 360));
            var cssH = Math.max(1, Math.round(layoutHeight || canvas.clientHeight || rect.height || options.height || 520));
            if (canvas.width !== Math.round(cssW * dpr) || canvas.height !== Math.round(cssH * dpr)) {
                canvas.width = Math.round(cssW * dpr);
                canvas.height = Math.round(cssH * dpr);
            }
            ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
            ctx.clearRect(0, 0, cssW, cssH);
            return { width: cssW, height: cssH, dpr: dpr };
        }

        function render(state) {
            if (destroyed) return null;
            lastState = state || lastState || { gender: '男', keyMap: {} };
            var nowMs = window.performance && window.performance.now ? window.performance.now() : Date.now();
            var size = setupCanvas();
            var measured = resolveMeasurement(manifest, lastState, options);
            var gender = measured.gender;
            var rigState = measured.rigState;
            var stateContext = measured.stateContext;
            var holders = measured.holders;
            var strictFields = measured.strictFields;
            var drawHolders = holdersForDraw(holders, lastState.drawFields || options.drawFields, strictFields);
            var contentBounds = measured.bounds;
            var fitEnvelope = normalizeBounds(lastState.fitEnvelope)
                || normalizeBounds(options.fitEnvelope);
            var bounds = fitEnvelope || copyBounds(contentBounds);
            var margin = numberOr(lastState.margin, numberOr(options.margin, 24));
            var w = Math.max(1, bounds.maxX - bounds.minX);
            var h = Math.max(1, bounds.maxY - bounds.minY);
            var scale = Math.min((size.width - margin * 2) / w, (size.height - margin * 2) / h);
            var zoom = numberOr(lastState.zoom, numberOr(options.zoom, 0.92));
            var maxScale = Math.max(0.1,
                numberOr(lastState.maxScale, numberOr(options.maxScale, 3)));
            scale = Math.max(0.1, Math.min(maxScale, scale * zoom));
            var offsetX = (size.width - (bounds.minX + bounds.maxX) * scale) / 2;
            // vAlign 'top'：把 fit 区域顶部锚到上边距（默认居中）。用于对话胸像取景——头部齐顶、
            // 身体向下溢出由画布裁切，与 NPC 立绘的固定窗口取景对齐。opt-in，不影响其他面板。
            var vAlign = lastState.vAlign || options.vAlign || 'center';
            var offsetY = (vAlign === 'top')
                ? (margin - bounds.minY * scale)
                : (size.height - (bounds.minY + bounds.maxY) * scale) / 2;

            ctx.save();
            ctx.translate(offsetX, offsetY);
            ctx.scale(scale, scale);
            var needsAnimation = false;
            var missing = 0;
            var pendingImages = 0;
            var failedImages = 0;
            function imageDrawable(image) {
                return !!(image && image.complete && image.naturalWidth > 0);
            }
            function imagePending(image) {
                return !!(image && !image.complete);
            }
            function imageErrored(image) {
                return !!(image && image.complete && !(image.naturalWidth > 0));
            }
            function drawLayer(layer, nowMs) {
                if (!layer || !layer.export) return;
                var selected = selectSkinFrame(layer, nowMs, fallbackFps);
                needsAnimation = needsAnimation || selected.animated;
                var frame = selected.frame;
                var uri = resolveImageUri(frame && frame.uri, manifest);
                var image = loadImage(imageCache, uri, function() { render(lastState); });
                ctx.save();
                applyMatrix(ctx, matrixFrom(layer.matrix));
                nestedLayers(layer, 'under').forEach(function(childLayer) {
                    drawLayer(childLayer, nowMs);
                });
                if (imageDrawable(image)) {
                    drawFrameImage(ctx, layer, frame, image);
                } else if (imagePending(image)) {
                    pendingImages++;
                } else if (imageErrored(image)) {
                    failedImages++;
                }
                nestedLayers(layer, 'over').forEach(function(childLayer) {
                    drawLayer(childLayer, nowMs);
                });
                ctx.restore();
            }
            drawHolders.forEach(function(holder) {
                var renderable = renderableForHolder(holder, manifest, lastState.keyMap, stateContext);
                if (!renderable.entry) {
                    if (renderable.key) missing++;
                    if (!debugPlaceholders) return;
                }
                // TODO(syncFrameToBasic): manifest emits holder.syncFrameToBasic === true for
                //   head holders. AS2 contract (bake-dressup-offline.py):
                //     "gotoAndStop(this.基本款._currentframe)"
                //   i.e. an attached head skin must NOT run its own clock — it should display the
                //   frame whose index equals the sibling 基本款 (basic head) holder's current frame.
                //   Not implemented here: these holders carry basic === null, so the index must come
                //   from a DIFFERENT sibling holder, but this per-holder forEach renders each holder
                //   in isolation with no shared current-frame map. Wiring it would require a pre-pass
                //   to compute the basic head holder's frame index for nowMs, then selecting this
                //   skin's frame by that index instead of selectSkinFrame's own clock. Deferred to
                //   avoid destabilizing the working independent-holder render; sync holders currently
                //   animate on their own clock (visually close for single-frame head skins).
                var selected = selectSkinFrame(renderable.entry, nowMs, fallbackFps);
                needsAnimation = needsAnimation || selected.animated;
                var frame = selected.frame;
                var uri = resolveImageUri(frame && frame.uri, manifest);
                var image = loadImage(imageCache, uri, function() { render(lastState); });
                if (renderable.entry && imagePending(image)) pendingImages++;
                else if (renderable.entry && imageErrored(image)) failedImages++;
                ctx.save();
                applyMatrix(ctx, matrixForRenderable(holder, renderable));
                if (renderable.entry) {
                    nestedLayers(renderable.entry, 'under').forEach(function(layer) {
                        drawLayer(layer, nowMs);
                    });
                }
                if (renderable.entry && image && image.complete && image.naturalWidth > 0) {
                    drawFrameImage(ctx, renderable.entry, frame, image);
                } else if (debugPlaceholders) {
                    drawPlaceholder(ctx, holder, renderable.key, renderable.covered);
                }
                if (renderable.entry) {
                    nestedLayers(renderable.entry, 'over').forEach(function(layer) {
                        drawLayer(layer, nowMs);
                    });
                }
                ctx.restore();
            });
            ctx.restore();
            if (needsAnimation && animationEnabled) scheduleAnimation();
            var result = {
                gender: gender,
                rig: rigState.rig,
                stateLabel: rigState.stateLabel,
                holders: drawHolders.length,
                totalHolders: holders.length,
                strictFields: strictFields,
                bounds: bounds,
                contentBounds: copyBounds(contentBounds),
                fitEnvelopeApplied: !!fitEnvelope,
                scale: scale,
                offsetX: offsetX,
                offsetY: offsetY,
                animated: needsAnimation,
                missing: missing,
                pendingImages: pendingImages,
                failedImages: failedImages
            };
            if (typeof options.onRender === 'function') options.onRender(result);
            return result;
        }

        return {
            render: render,
            measure: function(state) {
                if (destroyed) return null;
                return measureState(
                    manifest,
                    state || lastState || { gender:'男', keyMap:{} },
                    options
                );
            },
            measureEnvelope: function(state, variants, padding) {
                if (destroyed) return null;
                return measureEnvelope(manifest, state, variants, options, padding);
            },
            setManifest: function(nextManifest) {
                manifest = nextManifest;
            },
            getManifest: function() { return manifest; },
            setAnimationEnabled: function(enabled) {
                animationEnabled = enabled !== false;
                lastAnimationRenderAt = null;
                if (!animationEnabled && animationRequest !== null) {
                    window.cancelAnimationFrame(animationRequest);
                    animationRequest = null;
                } else if (animationEnabled && lastState) {
                    render(lastState);
                }
                return animationEnabled;
            },
            isAnimationEnabled: function() { return animationEnabled; },
            setPixelRatio: function(nextPixelRatio) {
                var next = Number(nextPixelRatio);
                if (next > 0 && isFinite(next)) configuredPixelRatio = next;
                return lastState ? render(lastState) : null;
            },
            destroy: function() {
                destroyed = true;
                lastState = null;
                if (animationRequest !== null) {
                    window.cancelAnimationFrame(animationRequest);
                    animationRequest = null;
                }
            }
        };
    }

    return {
        loadManifest: loadManifest,
        collectItemsByUse: collectItemsByUse,
        buildStateFromEquipment: buildStateFromEquipment,
        measureState: measureState,
        measureEnvelope: measureEnvelope,
        withFitEnvelope: withFitEnvelope,
        create: create
    };
})();
